def intersperse(numbers: List[int], delimeter: int) -> List[int]:
    result = []
    for i in range(len(numbers)):
        if numbers[i] is not None:
            result.append(numbers[i])
            if i < len(numbers) - 1 and (i + 2 <= len(numbers)) == False:
                result.insert(i+1, delimeter)
    return result

