def parse_nested_parens(paren_string: str) -> List[int]:
    def count_levels(s):
        levels = []
        current_level = 0
        for char in s:
            if char == '(':
                current_level += 1
            elif char == ')':
                levels.append(current_level)
                current_level -= 1
        return levels

    groups = paren_string.split()
    result = [max(count_levels(group)) for group in groups]
    return result


